#include "teaching/information.hpp"
#include <algorithm>

namespace observatory {
const std::vector<InformationArticle>& informationArticles() {
    static const std::vector<InformationArticle> articles{
        {"explore", "Explore the Game Boy", 
         "Click a memory byte, CPU register, system part, sprite, tile, map cell, or captured write. This space follows your most recent selection and explains the hardware behind it. The explanations work with the bundled examples and with your own ROMs.",
         "<p>A running game is a conversation between parts of a computer. The CPU executes instructions from the cartridge, uses RAM for temporary data, and writes hardware registers to control input, graphics, timers, and sound. The graphics hardware combines tile patterns, tile maps, and sprite records into a picture.</p><p>Start with something visible: select a sprite or tile. Or select a changing memory byte and look at its retained writer. Follow the related topics below to understand the connection, without needing to follow a prescribed sequence.</p>",
         "<p>Run with F5, pause to look around, step one instruction with F10, or advance to the next completed output with F11. Clicking an item or reading a topic does not run, restart, or replace the game. F9 is an explicit execution command: it runs until the selected address is written, or a limit is reached.</p><p>The topic chooser lets you read the whole reference. Back and Forward revisit recent selections. You can resize, move, or float this panel for longer reading; Help → Selection info (F1) brings it back.</p>",
         "<p>The selection facts are observed values at the shared state boundary. The article below them explains general hardware behavior; it does not guess what an arbitrary game's variables mean. The picture, activity counts, and captured history have their own labeled times. Seeing a connection is useful evidence, but does not by itself prove the complete cause of a screen pixel.</p>",
         {"memory", "cpu", "tile-data", "tile-map", "oam", "time"}},
        {"memory", "Memory · the CPU's address space",
         "Memory gives the CPU places to fetch instructions, read data, and write results. An address is a numbered location; the byte stored there is its value. The same value can represent a number, an instruction, a tile pattern, or a control bit, depending on how the program and hardware use it.",
         "<p>The Game Boy uses 16-bit addresses: $0000 through $FFFF, or 65,536 possible byte locations. A byte has 8 bits and holds a value from 0 to 255. A dollar sign means hexadecimal (base 16): $10 is decimal 16, $FF is 255. Two hexadecimal digits describe one byte; four describe an address. One KiB means 1,024 bytes.</p><p>This is an <b>address space</b>, not 64 KiB of interchangeable RAM. Different ranges connect to different storage and devices:</p><table cellspacing='5'><tr><th>Range</th><th>What lives here</th></tr><tr><td>$0000–$3FFF</td><td>Lower cartridge ROM window</td></tr><tr><td>$4000–$7FFF</td><td>Upper cartridge ROM window, often switchable</td></tr><tr><td>$8000–$9FFF</td><td>Video RAM: tile patterns and two tile maps</td></tr><tr><td>$A000–$BFFF</td><td>Cartridge RAM or selected cartridge hardware</td></tr><tr><td>$C000–$DFFF</td><td>Work RAM</td></tr><tr><td>$E000–$FDFF</td><td>Echo of $C000–$DDFF</td></tr><tr><td>$FE00–$FE9F</td><td>Sprite records (OAM)</td></tr><tr><td>$FEA0–$FEFF</td><td>No ordinary storage</td></tr><tr><td>$FF00–$FF7F</td><td>Hardware input/output registers</td></tr><tr><td>$FF80–$FFFE</td><td>High RAM</td></tr><tr><td>$FFFF</td><td>Interrupt enable register</td></tr></table>",
         "<p>An instruction might load a byte from work RAM into register A, add one, and store it back. Another might write a tile number into a map, or write a bank-selection command to an address in the ROM range. Some multi-byte quantities are stored with the low byte first (little-endian); the meaning is determined by the code using them.</p><p>Banks and mirrors matter. The same CPU address can reach a different cartridge bank later, while two echo addresses can reach the same physical RAM byte. A memory location is identified by its mapping as well as its address.</p>",
         "<p>The Memory table shows 128 bytes of copied storage at the state boundary. Gold marks compare against the previous displayed snapshot. It does not mean every highlighted byte was written by the most recent instruction. The table avoids simulated CPU reads: hardware bus restrictions and register readback can differ from the stored bytes shown here.</p><p>Select a byte to read its region's explanation and inspect retained write evidence. Capture is bounded, so an absent writer can mean history was evicted, capture was off, or the change came from hardware. Only the exact bundled ROMs receive source-defined variable names.</p>",
         {"wram", "rom", "vram", "io", "banks", "writes"}},
        {"rom", "ROM · program and fixed data",
         "Read-only memory on the cartridge holds the game's program and resources. The CPU's $0000–$7FFF windows expose up to 32 KiB at once, even when the cartridge file is much larger.",
         "<p>Instructions are stored as numeric opcode bytes, followed by any operands. ROM also holds graphics, text, level layouts, and other data. Being in ROM does not make a byte an instruction: the CPU executes it only when the program counter reaches it.</p><p>Small cartridges connect their ROM directly. Larger ones use a memory bank controller (MBC) to choose the visible banks. The lower 16 KiB window is often fixed, but some controllers can remap it. A CPU write to the ROM range normally commands the controller; it does not modify the game file.</p>",
         "<p>A game can keep common code in the lower window and switch level data or routines into the upper window. Calling $4000 can execute different code after a bank change. The cartridge header describes the expected hardware, ROM size, title, and compatibility flags; the effective controller can differ for unusual or multicart images.</p>",
         "<p>The view names the currently mapped bank, and captured instructions retain their bank identity. An address alone is insufficient to identify code in a banked game. The boot program can temporarily cover $0000–$00FF during startup. Disassembly is a decoding of current storage, not proof that the CPU executed those bytes.</p>",
         {"banks", "cartridge", "instructions", "boot", "memory"}},
        {"wram", "Work RAM · the game's temporary workspace",
         "Work RAM (WRAM) is the original Game Boy's 8 KiB of general-purpose read/write memory, at $C000–$DFFF. Games use it for values that change while they run.",
         "<p>The CPU reads a value into a register, works on it, and writes the result back. Work RAM can hold positions, counters, temporary calculations, decompressed data, a stack, or a prepared copy of sprite records. None of these meanings is built into a WRAM address: the program decides the layout.</p><p>The range $E000–$FDFF mirrors the first $1E00 bytes of WRAM. These are two address routes to the same storage, not two independent copies. WRAM belongs to the console and is distinct from battery-backed RAM on a cartridge.</p>",
         "<p>A game might update a position in WRAM, convert it into sprite coordinates in a shadow table, then transfer that table to OAM. Looking at WRAM and a captured writer can expose one link in that process. In the exact bundled star example, source annotations identify its position variables; other games receive only hardware facts.</p>",
         "<p>The table shows storage at the shared state boundary. A changed byte is not automatically a player's position or score. Retained writers can explain a store without explaining all earlier calculations. Echo addresses are resolved to the same physical WRAM for writer matching, and writes caused by hardware are not invented as CPU instructions.</p>",
         {"memory", "echo", "registers", "stack", "dma", "writes"}},
        {"echo", "Echo RAM · two addresses, one storage location",
         "The $E000–$FDFF range mirrors $C000–$DDFF. An address in the echo range reaches the WRAM byte $2000 lower; it does not add more RAM.",
         "<p>For example, $E123 and $C123 identify the same physical byte. A store through either route changes what the other route shows. This is a feature of the console's address decoding, rather than a software copy that happens later. The mirror stops at $FDFF, before the sprite table.</p>",
         "<p>Mirrors illustrate why an address and a physical location are different ideas. If a writer used $E123 but you selected $C123, that writer is still relevant. Programs generally use the normal WRAM range; the echo range is discouraged for game code.</p>",
         "<p>This app canonicalizes echo addresses when matching retained writers. A count in the activity map is attached to the CPU address used by the instruction, so aliases can have different access counts even though their contents represent the same storage.</p>",
         {"memory", "wram", "activity", "writes"}},
        {"vram", "Video RAM · graphics storage",
         "Video RAM (VRAM) is 8 KiB at $8000–$9FFF in monochrome Game Boy mode. It stores reusable tile patterns and maps that arrange those patterns into a background or window.",
         "<p>$8000–$97FF contains 384 tile patterns, each 16 bytes. $9800–$9BFF and $9C00–$9FFF are two 1,024-byte tile maps. A pattern describes eight rows of pixels; a map entry names a pattern to place at one position. Sprite records in OAM also refer to patterns in VRAM.</p><p>The pixel processing unit (PPU) reads this storage while drawing. During pixel transfer, the CPU cannot normally access VRAM. Games schedule graphics updates during permitted periods, often vertical blanking. A write attempt during a blocked period need not change the stored byte.</p>",
         "<p>Changing a pattern can alter every map cell or sprite that refers to it. Changing a map entry chooses another pattern for just that position. A scrolling background can reuse the same patterns across many cells, saving space compared with storing a full bitmap.</p>",
         "<p>The tile and map views decode copied VRAM at the current boundary. They are a reconstruction of current storage, not a record of each PPU fetch in the completed picture. Palette, map-selection, and addressing registers affect how the bytes are interpreted.</p>",
         {"tile-data", "tile-map", "oam", "ppu", "palettes", "writes"}},
        {"tile-data", "Tiles · reusable 8×8 pixel patterns",
         "A tile is an 8×8 pattern with four possible colour numbers per pixel. Its 64 pixels are encoded in 16 bytes of VRAM. Tile data can be reused by background cells, window cells, and sprites.",
         "<p>Each row uses two bytes called bit planes. The first supplies the low bit of every pixel's colour number; the second supplies the high bit. Bit 7 is the leftmost pixel. Combine the two bits as <b>high × 2 + low</b>, giving 0, 1, 2, or 3. For example, low 1 and high 0 produce colour 1; low 0 and high 1 produce colour 2.</p><p>A palette then maps that number to a shade. The pattern itself does not specify a final display shade. Colour number 0 is transparent when used by a sprite, but is an ordinary background colour.</p><p>The pattern area has three blocks: $8000–$87FF, $8800–$8FFF, and $9000–$97FF. Sprites always use unsigned numbers based at $8000. Background/window maps use either unsigned $8000 addressing or signed offsets from $9000, controlled by LCDC bit 4. In signed mode, entry $00 selects the pattern at $9000 and $FF selects $8FF0. The inspector's 0–383 numbering names physical pattern slots, not always the map's 0–255 entry value.</p>",
         "<p>A game can animate by replacing a sprite's tile number, editing one pattern, or changing map entries. One pattern can appear many times. Select a tile in the sheet to keep that physical pattern pinned; select a sprite to follow its changing tile instead. Click a bit-plane row to open its two source bytes in Memory.</p>",
         "<p>Usage marks come from current map entries and sprite records. A referenced pattern is not necessarily visible: scrolling, window coverage, sprite limits, and priority affect output. The decoded tile does not prove which bytes were fetched when an older screen pixel was drawn.</p>",
         {"tile-map", "palettes", "vram", "oam", "lcdc", "display"}},
        {"tile-map", "Tile maps · arranging patterns into a picture",
         "A tile map is a grid of tile numbers, not a grid of full pixel patterns. The Game Boy has two 32×32 maps in VRAM at $9800 and $9C00; each occupies 1,024 bytes and describes a 256×256-pixel arrangement.",
         "<p>For a cell at column x and row y, its address is <b>map base + y × 32 + x</b>. The stored byte chooses a tile pattern. The pattern's actual address also depends on LCDC bit 4: unsigned numbers start at $8000; signed numbers are offsets from $9000. Both maps can refer to the same pattern data.</p><p>LCDC bit 3 selects the background map; bit 6 selects the window map. These are independent choices, so the two layers may share a map or use different ones. On the monochrome system, map cells do not contain per-cell palette or flip attributes; those are Game Boy Color features.</p>",
         "<p>The 160×144 screen shows a viewport into the larger background. SCX and SCY scroll it, wrapping around at the map edges. The window can replace part of the background with a separate map positioned using WX and WY. Repeating tile numbers reuse graphics efficiently: a floor or wall can use one pattern in many cells.</p><p>Select a cell in the map view to see its coordinates, map byte, and currently resolved pattern. Its pattern also opens in the tile detail. The Memory panel follows the map entry so retained CPU writers can be inspected.</p>",
         "<p>The map view reconstructs all 1,024 cells using current VRAM, addressing mode, and background palette. It is not the completed screen: it does not apply the scroll viewport, window overlay, sprites, or mid-frame register changes. A cell can be present even while its layer is disabled. The selected entry and selected physical tile are different locations; changing either can change the reconstructed result.</p>",
         {"tile-data", "scroll", "window", "palettes", "lcdc", "ppu"}},
        {"oam", "Sprites and OAM · movable graphics",
         "Object attribute memory (OAM) is the 160-byte sprite table at $FE00–$FE9F. It holds 40 four-byte records describing movable objects, commonly called sprites.",
         "<p>Each record contains Y, X, tile number, and attributes, in that order. Stored coordinates include offsets: screen X = X − 8, screen Y = Y − 16. A zero coordinate can hide a sprite. Attributes choose background priority, vertical flip, horizontal flip, and one of two object palettes. The pixels themselves live in VRAM.</p><p>LCDC bit 2 chooses 8×8 or 8×16 sprites for the whole display. In 8×16 mode the tile number's low bit is ignored: an even pattern forms the top and the next pattern forms the bottom. Sprite colour 0 is transparent. On DMG, only ten sprites are selected per scanline; overlap, priority, and background pixels can further hide them.</p>",
         "<p>Moving a sprite usually changes its X/Y bytes rather than its graphics. Animation changes the tile reference. Many games prepare all 40 records in a WRAM shadow table, then use OAM DMA to copy them efficiently. Others use CPU stores where hardware access permits.</p><p>Click a sprite in the game or a row in the table to follow its current record and tile. Selecting a standalone tile stops following the sprite's animation.</p>",
         "<p>The overlay shows current OAM rectangles; a rectangle overlapping the screen does not prove that its pixels were visible. OAM may be newer than the last completed picture. CPU access is restricted during sprite search/pixel transfer and DMA. DMA observations describe requests and later checks, not byte-by-byte provenance.</p>",
         {"tile-data", "palettes", "dma", "ppu", "display", "writes"}},
        {"cart-ram", "Cartridge RAM · data outside the console",
         "Some cartridges include writable memory accessed through $A000–$BFFF. It is separate from the console's WRAM and can hold persistent progress when the cartridge supplies a battery or other nonvolatile storage.",
         "<p>A controller can select which 8 KiB RAM bank is visible in this window and can enable or disable CPU access. Smaller RAM sizes may mirror within the window. Some controllers expose other hardware here: an MBC3 can select a real-time-clock register instead of RAM, and other cartridges have sensors or special storage.</p><p>MBC2 has 512 four-bit entries rather than ordinary byte-wide RAM. The interpretation depends on the cartridge, so the current mapping and controller type matter as much as the address.</p>",
         "<p>Games save progress by writing their chosen data structure, not by saving the whole machine. A battery file contains cartridge storage and, where supported, clock state. Two stores to $A000 in different banks can affect different data even though their CPU addresses match.</p>",
         "<p>This inspector shows available RAM storage through the public core API. The RAM-enable latch is not exposed, so showing a stored byte does not establish what a CPU bus read would return. Writer matching includes the physical RAM bank and mirrors. Save status is separate from the emulated RAM contents: a successful store can still be waiting for a disk autosave.</p>",
         {"banks", "battery", "cartridge", "memory", "writes"}},
        {"unusable", "Unusable range · no ordinary byte storage",
         "$FEA0–$FEFF lies between the sprite table and hardware registers. It is not general-purpose RAM, and should not be treated as a place to keep variables.",
         "<p>Address decoding does not connect this range to ordinary storage. What a real CPU read observes can depend on the model and hardware state; it is not a dependable zero-filled memory block. Writing here does not create a writable byte for the game to read back.</p>",
         "<p>The gap is a useful reminder that an address space describes possible bus addresses, not a promise that every address owns memory. Similar caution applies to unused hardware registers and cartridge windows with no RAM installed.</p>",
         "<p>A dash in the Memory table means the adapter has no storage value to show. It is not the result of a simulated CPU bus read and does not claim a universal value for that address. A captured attempt can still name an address without proving an accepted write.</p>",
         {"memory", "oam", "io", "writes"}},
        {"io", "Hardware registers · controlling the machine",
         "The $FF00–$FF7F range contains memory-mapped input/output (IO) registers. Reading or writing their addresses communicates with hardware rather than merely storing a game variable.",
         "<p>A register can expose button input, a running timer, the current scanline, or a configuration such as the palette. Individual bits often have different jobs. Some bits are read-only, some unused bits read as one, and some writes trigger actions instead of storing the written value unchanged.</p><p>For example, writing any value to DIV resets the divider. Writing $C1 to DMA requests a copy from $C100–$C19F into OAM. LCDC chooses graphics features and tile addressing. Interrupt requests live in IF at $FF0F, while their enable mask lives separately at $FFFF.</p>",
         "<p>These registers are the boundary between code and hardware behavior. An instruction that writes one can change what the rest of the system does over subsequent cycles. The effect can be delayed: a display update is drawn progressively, and a DMA request is followed by a transfer.</p>",
         "<p>This app reads copied raw register storage for inspection so viewing a register does not advance or synchronize hardware. Raw storage can differ from CPU bus readback. A captured write's requested value is a command; before/after register bytes alone are not proof of its full effect. Select a recognized register to read its relevant topic and concise register-specific explanation.</p>",
         {"joypad", "timers", "interrupts", "lcdc", "dma", "audio", "serial"}},
        {"hram", "High RAM · a small, useful workspace",
         "High RAM (HRAM) is 127 bytes at $FF80–$FFFE. It is ordinary writable console storage in a small address range next to the hardware registers. $FFFF is interrupt enable, not HRAM.",
         "<p>Instructions using the high-memory addressing forms can reach this range with a one-byte offset from $FF00. The same instruction forms also reach IO registers, but HRAM stores ordinary data. HRAM remains accessible to the DMG CPU while an OAM DMA transfer restricts most other bus accesses.</p>",
         "<p>Games often put a short DMA-start/wait routine here. HRAM can also hold frequently accessed variables or small pieces of executable code. Its name describes its location in the address space, not a different kind of programmer-visible byte.</p>",
         "<p>The contents are current copied storage, and physical before/after values can be inspected for captured CPU attempts. Executing code here is counted by its HRAM address rather than a cartridge bank. A nearby address such as $FF46 or $FFFF has a different hardware role despite sharing the same high-memory instruction forms.</p>",
         {"memory", "dma", "io", "instructions", "interrupts"}},
        {"cpu", "CPU · the processor that runs the program",
         "The Game Boy's Sharp SM83 CPU executes the instructions that make a game work. It moves values between registers and memory, performs arithmetic, tests conditions, and changes where execution continues.",
         "<p>The program counter (PC) identifies the next instruction. Its opcode selects an operation; operand bytes can supply a constant or address. Registers are small storage locations inside the processor. Flags record certain results so later instructions can make decisions. Instructions take different amounts of time, allowing other hardware to progress between and during them.</p><p>Calls use the stack to save a return address. Interrupts can redirect execution to a handler when requests, enable bits, and the CPU's master enable permit it. HALT can stop opcode execution while hardware and emulated time continue.</p>",
         "<p>A game loop reads input, updates state, prepares graphics, and coordinates with hardware. Following a changing byte's writer can reveal one operation in that loop. An instruction such as LD [$C000], A means copy A into memory; it does not say what the game's author intended that byte to represent.</p>",
         "<p>The CPU panel shows an atomic execution boundary. The next disassembly is storage at PC and has not yet executed. The last opcode is separate from interrupt or wait work. Instruction stepping can advance time while halted before an opcode runs; this is different from freezing every component between individual clock cycles.</p>",
         {"registers", "flags", "instructions", "stack", "interrupts", "time"}},
        {"registers", "Registers · the CPU's immediate workspace",
         "Registers hold the values the processor is working with right now. The Game Boy has the 8-bit registers A, F, B, C, D, E, H, and L, plus the 16-bit stack pointer SP and program counter PC.",
         "<p>The panel groups byte registers into AF, BC, DE, and HL. The first letter is the high byte: if HL is $C123, H is $C1 and L is $23. A is the accumulator used by many arithmetic and memory operations. F holds flags rather than ordinary general-purpose data; its low four bits are unused.</p><p>BC, DE, and HL can be used as pairs in 16-bit operations. HL commonly points to a memory byte, but it is not permanently a pointer: instructions decide how a register is used. PC identifies instruction storage, while SP identifies the top of the stack.</p>",
         "<p>A typical update loads memory into A, changes it, and stores it back. Register contents are temporary: the same register can hold a position in one routine and a loop counter in another. Selecting a register tells you its architectural role, not an inferred role in an unknown game.</p>",
         "<p>These are copied current values at the shared boundary. Gold marks compare with the prior displayed snapshot. Pair values use four hexadecimal digits; a displayed byte inside a pair has its own two-digit value. The exact register operation and flag behavior depend on the instruction being executed.</p>",
         {"cpu", "flags", "instructions", "memory", "stack"}},
        {"flags", "Flags · small results that guide decisions",
         "The upper four bits of register F hold Z, N, H, and C. These flags help the CPU make conditional decisions and implement arithmetic, but their meaning depends on the instruction that set them.",
         "<p><b>Z (zero)</b> records a zero result for instructions that update it. <b>N (subtract)</b> distinguishes subtraction from addition for decimal adjustment. <b>H (half carry)</b> records a carry or borrow across a smaller arithmetic boundary, commonly bit 3 for 8-bit operations. <b>C (carry)</b> records an arithmetic carry/borrow or a bit shifted out, depending on the operation.</p><p>Not every instruction changes every flag. A load can leave them unchanged, and some operations force particular flags to zero. Comparing with CP updates flags as if subtracting, without storing the arithmetic result in A. Conditional jumps can test Z or C.</p>",
         "<p>A program can compare a counter with a limit and branch when the zero flag is set. Carry can connect multi-byte arithmetic: ADC adds an operand and the existing carry. Half carry and subtract support DAA, which adjusts results for binary-coded decimal.</p>",
         "<p>A set flag is not a permanent description of the entire machine. It reflects the last relevant instruction, which may have run earlier than the last opcode. The selected flag's concise explanation identifies its bit; examine disassembly and actual values before interpreting why a branch will be taken.</p>",
         {"registers", "instructions", "cpu", "time"}},
        {"instructions", "Instructions · decoding program bytes",
         "An instruction is a small operation selected by an opcode byte. Additional bytes can supply immediate data or an address. The disassembler turns these bytes into readable names such as LD, INC, ADD, JP, CALL, and RET.",
         "<p>LD copies a value; INC increments; arithmetic combines values and may change flags. A bracketed operand such as [HL] means memory at the address held in HL, not HL itself. Immediate 16-bit operands are stored low byte first. Jumps change PC; calls also save a return address on the stack.</p><p>Instruction lengths and timings vary. A conditional branch can take different time depending on whether it is taken. The displayed next instruction is decoded from current storage at PC. Bank mapping matters if that storage is in cartridge ROM.</p>",
         "<p>A captured write can show which instruction attempted a store and what value it requested. This helps connect code to changing state. Register changes and hardware progress between boundaries give additional evidence, but one store rarely explains all the calculations that produced its value.</p>",
         "<p>Disassembly is not automatically a source program: ROM contains data as well as code. A next opcode may be interrupted before execution, and HALT/wait work is not a fabricated opcode. Captured event start/end times enclose an engine step; they are not the exact bus cycle of each write. Selecting evidence does not rewind the machine.</p>",
         {"cpu", "registers", "flags", "stack", "banks", "writes"}},
        {"stack", "The stack · remembering where to return",
         "The stack is a software-managed area of writable memory addressed by the CPU's stack pointer, SP. It stores return addresses and temporary register values. There is no permanently reserved stack RAM range.",
         "<p>The Game Boy stack grows toward lower addresses. PUSH stores a register pair while decreasing SP; POP retrieves it while increasing SP. CALL and interrupt entry save a return address, and RET/RETI restore it to PC. A saved 16-bit value occupies two bytes, with its low byte at the lower address.</p><p>The program chooses an initial SP in suitable writable memory. Stack operations consume space, so deeply nested calls or an incorrectly initialized pointer can overwrite variables or hardware addresses.</p>",
         "<p>A function can call another function and return to the instruction after the call. Saving register pairs lets a routine preserve values its caller still needs. Interrupt handlers use the same idea, and must account for where the stack resides when bus access is restricted by DMA.</p>",
         "<p>The panel shows the current pointer, not a reconstructed call history. Retained stores near SP can provide evidence, but complete stack unwinding requires knowledge of the program's conventions and earlier execution. General RAM explanations do not assign arbitrary bytes a stack role.</p>",
         {"registers", "instructions", "wram", "hram", "interrupts", "dma"}},
        {"cartridge", "Cartridge · program, storage, and extra hardware",
         "The cartridge supplies the game's ROM and may also include writable save memory, a bank controller, a real-time clock, or other hardware. A ROM file is an image of program storage, not an image of the whole running console.",
         "<p>The header records a title, controller type, expected ROM/RAM sizes, and model flags. The emulator uses these and supported cartridge conventions to configure the mapping. Some unusual images require an effective controller interpretation that differs from their declared header.</p><p>The CPU sees ROM through two 16 KiB windows and cartridge RAM through an 8 KiB window. A controller can expose different banks or devices in those windows. Power-on also runs a boot program before the game's entry point.</p>",
         "<p>Bank switching lets a cartridge hold more code and data than the CPU can address simultaneously. Persistent memory lets a game save progress. Clock-equipped cartridges can maintain time separately from the console's short-interval timer hardware.</p>",
         "<p>The Cartridge panel shows the effective supported controller, live mapping, retained controller writes, and execution counts by ROM bank. Compatibility flags are information, not a promise that a Color-only game works in this monochrome lab. Cartridge details do not identify unknown game variables or provide a full compatibility survey.</p>",
         {"rom", "banks", "cart-ram", "battery", "boot", "activity"}},
        {"banks", "Banks · more storage than one address window",
         "A bank is a chunk of cartridge memory that can be connected to a CPU address window. The memory bank controller (MBC) chooses the mapping in response to program writes.",
         "<p>The lower ROM window is $0000–$3FFF, the upper is $4000–$7FFF, and cartridge RAM uses $A000–$BFFF. A ROM bank is usually 16 KiB, while a RAM bank is usually 8 KiB. MBC1, MBC3, MBC5, and other controllers have different commands, bank-number rules, and extra features.</p><p>A store to $2000 might choose another ROM bank rather than change ROM. The effect is visible in the mapping before and after the step. The lower window is often fixed, but MBC1 modes and other controllers can remap it too. A bank exists even when it is not currently visible.</p>",
         "<p>A game can switch in a new level, graphic set, or routine while keeping common code accessible. The same PC or RAM address can then refer to different physical storage. In the bundled bank example, A (keyboard Z) causes a real switch; the generic Run until the bank changes control waits for a mapping change rather than driving a tutorial.</p>",
         "<p>Lines in the bank diagram show current connections; shading summarizes opcode starts over a labeled interval. Selecting an unmapped bank explains it but does not force a bank switch. Historical writes retain their original bank; current memory keeps the current mapping. MMM01 can rearrange storage, so displayed linear file offsets have a caveat for that controller.</p>",
         {"cartridge", "rom", "cart-ram", "writes", "activity", "memory"}},
        {"battery", "Battery saves · keeping cartridge progress",
         "Battery-backed cartridge storage keeps selected game data across power cycles. The app saves this storage to a .sav file, normally next to the ROM. This is different from a save state of the entire console.",
         "<p>The game itself decides which bytes mean progress and when to write them. Depending on the controller, a save also includes supported clock or other persistent state. Resetting the CPU keeps cartridge save storage, while loading a different ROM creates a different session.</p><p>The app validates a save before changing live RAM and protects an unreadable or incompatible existing file from automatic overwrite. New progress can be saved to another destination. Writes use an atomic file replacement so a partially written file is not intentionally installed as the completed save.</p>",
         "<p>Autosaving checks dirty cartridge storage every few seconds, including while paused. Save now requests a disk write; Save as chooses a new destination for future autosaves. If saving fails before closing or replacing a game, the recovery prompt lets you keep the game open, save elsewhere, or explicitly discard the unsaved progress.</p>",
         "<p>A dirty flag means cartridge data has changed since the last successful save, not that the CPU or graphics state has been saved. The persistent status reports disk errors and protected files. A .sav does not store CPU registers, VRAM, the current instruction, or the displayed frame; full save states are not implemented.</p>",
         {"cart-ram", "cartridge", "banks", "memory"}},
        {"joypad", "Joypad · turning buttons into input bits",
         "The joypad register P1 at $FF00 lets the CPU read the buttons. Games turn those bits into actions; the hardware does not itself know what movement, jumping, or a menu means.",
         "<p>The register selects direction and action-button groups using bits 4 and 5. The low four bits report selected buttons with active-low logic: a pressed button reads as 0. Direction and action groups reuse those bits. Input changes can request the joypad interrupt under the hardware's conditions.</p><p>This app maps arrows to directions, Z/X to A/B, and Enter/Backspace to Start/Select. A button can be held while execution is paused; its effect on game state occurs when the program and hardware next process it. Losing window focus releases held buttons.</p>",
         "<p>A game typically polls P1 or handles input during a frame update, then changes variables or graphics. The same physical button may have a different meaning in a menu or a level. Try a held input and an explicit frame step, then inspect changing memory and retained instructions.</p>",
         "<p>The held-button indicator and copied P1 storage are different observations. Raw register storage is not a synthesized CPU bus read of the selected button group. General explanations describe the input mechanism; only exact bundled ROM source annotations describe a specific game response. Reading this panel does not press a button for you.</p>",
         {"io", "interrupts", "wram", "cpu", "time"}},
        {"ppu", "PPU · building the picture over time",
         "The pixel processing unit (PPU) combines background/window tile maps and sprite records into the 160×144 display. It draws progressively, rather than producing an entire frame in one instant.",
         "<p>A normal DMG frame has 154 scanlines: 144 visible lines and 10 vertical-blank lines. Each line has 456 dots, giving 70,224 dots per frame, about 59.73 frames per second. A dot is one 4,194,304 Hz clock period in this mode.</p><p>During visible lines, the PPU searches OAM (mode 2), transfers pixels (mode 3), then enters horizontal blank (mode 0). Vertical blank is mode 1. Pixel-transfer length varies with rendering work. These phases restrict CPU access to VRAM/OAM and can request display interrupts through STAT.</p>",
         "<p>Games often update graphics during blanking periods. Scrolling, window placement, palette writes, sprite priority, and tile addressing all contribute to output. Changing a register partway through drawing can make different lines use different settings, so end-of-frame storage alone is not enough to reconstruct historical pixel inputs.</p>",
         "<p>The live mode and scanline come from the shared snapshot. Tile/map views decode storage at that boundary, while the game view shows a separately labeled completed output. This app does not record every PPU fetch or provide per-pixel provenance. A functional arrow in the system overview describes a connection, not a transistor-level circuit.</p>",
         {"display", "stat", "lcdc", "tile-map", "oam", "time"}},
        {"display", "The display · completed output and current state",
         "The game view shows the most recent completed emulator output, a 160×144 picture. CPU and storage inspectors can already be at a newer boundary than the picture's completion time.",
         "<p>The PPU draws visible scanlines using tile patterns, maps, palettes, and sprites. The emulator publishes completed output; the app copies it for display. Stepping a CPU instruction can change sprite coordinates or VRAM without completing another picture.</p><p>Sprite outlines use OAM at the current boundary. Changed-pixel marks compare the last two completed outputs. These overlays describe different observations: the outline can move ahead of the picture, while a changed pixel only says the two outputs differ.</p>",
         "<p>Use the output number and its age beside the game to compare times. A frame step advances to the next completed output and finishes its enclosing engine step. Click a sprite to inspect its record, or click empty display space to read about rendering without advancing the emulator.</p>",
         "<p>A current sprite rectangle is not a historical pixel attribution. A pattern can have changed after the displayed picture was drawn, and mid-frame effects can use multiple register values in one output. Startup or LCD-disabled output can be retained/artificial rather than a normal VBlank frame; the output-kind label distinguishes these cases.</p>",
         {"ppu", "oam", "tile-map", "palettes", "time"}},
        {"palettes", "Palettes · from colour numbers to shades",
         "A tile stores colour numbers 0–3. A monochrome palette register maps each number to one of four shades. Changing the palette can change appearance without editing the tile's bits.",
         "<p>BGP at $FF47 controls background/window mapping. OBP0 and OBP1 at $FF48/$FF49 provide two sprite mappings; an OAM attribute bit chooses between them. Each register uses two bits per colour number: bits 1–0 for number 0, 3–2 for 1, 5–4 for 2, and 7–6 for 3.</p><p>Shade values run from 0 (lightest) to 3 (darkest). For sprites, colour number 0 is always transparent, so its palette field does not provide an opaque sprite colour. Transparency depends on the number, not on whether its mapped shade would look white.</p>",
         "<p>A game can fade a scene or change contrast through a palette write. The same pattern can appear differently as background graphics or as a sprite, or under the two object palettes. The tile inspector can display raw colour numbers to separate pattern decoding from shade mapping.</p>",
         "<p>The reconstruction uses the palette at the current boundary, which may differ from the values used while an earlier picture was drawn. Monochrome mode has no per-map-cell colour palettes. Display colours are this app's chosen rendering of the four shades, rather than a claim about the physical LCD's exact colour response.</p>",
         {"tile-data", "oam", "tile-map", "io", "display"}},
        {"scroll", "Scrolling · a viewport into the background",
         "SCY at $FF42 and SCX at $FF43 choose the top-left pixel of the background viewport. The map is 256×256 pixels, while the visible screen is only 160×144.",
         "<p>The PPU adds scrolling offsets to screen coordinates to find background map cells and pixels within their tiles. Coordinates wrap modulo 256, so scrolling beyond one edge continues at the opposite edge. Offsets can be pixel-sized rather than whole-tile increments.</p><p>Changing SCX or SCY moves the viewport without rewriting every map entry. The background map selection and tile-addressing mode still come from LCDC. The window has separate placement and does not scroll using SCX/SCY.</p>",
         "<p>Games can move a camera across a level by adjusting scroll values and replacing map cells that enter view. The map can wrap physically even when the game's logical level is much larger. Mid-frame scroll changes can produce split or wavy scenes.</p>",
         "<p>The map reconstruction shows the whole grid, without applying the viewport. Current scroll storage does not establish the offset used for every line in the completed picture. Select map cells to understand the arrangement, and compare the display's separately labeled time when investigating a change.</p>",
         {"tile-map", "window", "lcdc", "ppu", "display"}},
        {"window", "The window · a second tile-map layer",
         "The Game Boy window is a hardware graphics layer placed over part of the background. It is often used for status bars or menus, but those game meanings are choices made by the program.",
         "<p>LCDC bit 5 enables the window and bit 6 chooses its map. On DMG, background/window enable in bit 0 also matters. WY at $FF4A sets the top screen row; WX at $FF4B uses an offset, so the horizontal start is WX − 7. The window uses the same tile-pattern addressing mode and background palette as the background.</p><p>The window starts from its map's top-left area rather than following SCX/SCY. Its internal line counter advances when the window is actually displayed, so unusual mid-frame enable or placement changes have timing details beyond a simple fixed overlay.</p>",
         "<p>A game can keep a score strip stable while scrolling the background behind it. The two layers may use the same map or different maps. Their tile numbers can refer to the same reusable patterns.</p>",
         "<p>Current WX/WY and LCDC describe current configuration, not necessarily the configuration used for every scanline of the completed output. The map viewer labels the selected layer and reconstructs its storage; it does not emulate window timing or compose sprites into that reconstruction.</p>",
         {"tile-map", "scroll", "lcdc", "palettes", "ppu"}},
        {"lcdc", "LCDC · configuring graphics hardware",
         "LCDC at $FF40 is a bit field controlling major graphics choices. Its bits enable the display/layers, select tile maps and addressing, and choose sprite height.",
         "<p>Bit 7 enables the LCD/PPU; bit 6 selects the window map; bit 5 enables the window; bit 4 chooses unsigned $8000 or signed $9000-based pattern addressing; bit 3 selects the background map; bit 2 chooses 8×8 or 8×16 sprites; bit 1 enables sprites; bit 0 enables background/window rendering in DMG mode.</p><p>For map-selection bits, 0 chooses $9800 and 1 chooses $9C00. Bit 4 affects background/window patterns, while sprites always use unsigned $8000-based tile numbers. A register write can therefore change how unchanged VRAM bytes are interpreted.</p>",
         "<p>A game configures LCDC during startup, then may change layer options for menus, effects, or scrolling scenes. Display disable is not simply replacing pixels with a new bitmap: it affects PPU operation and the emulator's output behavior.</p>",
         "<p>The displayed byte is raw storage at the shared boundary. Its current settings do not prove which settings were used for earlier output pixels. This lab runs DMG mode; some LCDC bits have different priority semantics in Game Boy Color mode, which is not implemented here.</p>",
         {"tile-map", "tile-data", "oam", "window", "ppu", "io"}},
        {"stat", "STAT and scanlines · where drawing is now",
         "STAT at $FF41 reports PPU status and selects display-interrupt sources. LY at $FF44 reports the scanline; LYC at $FF45 supplies a line value to compare against LY.",
         "<p>STAT bits 1–0 identify the PPU mode: horizontal blank (0), vertical blank (1), OAM search (2), or pixel transfer (3). Bit 2 reports the LY=LYC comparison. Bits 3, 4, 5, and 6 enable interrupt sources for horizontal blank, vertical blank, OAM search, and the coincidence condition.</p><p>These sources feed a combined STAT interrupt signal; they are not four independent unconditional calls. The separate VBlank interrupt is another source in IF/IE. Scanline and mode change as the PPU progresses, even if the CPU is waiting.</p>",
         "<p>Programs use blanking periods to schedule memory access and line comparisons to coordinate raster effects. A STAT or LY observation helps explain when an attempted VRAM/OAM access occurred relative to drawing.</p>",
         "<p>The inspector gives the mode and storage at the boundary, not a per-dot timeline of the whole instruction. Raw STAT bytes can differ from bus readback. An enabled source does not prove that a handler ran: interrupt requests, IE, and the CPU master enable all participate.</p>",
         {"ppu", "interrupts", "vram", "oam", "time", "io"}},
        {"dma", "OAM DMA · transferring the sprite table",
         "Direct memory access (DMA) lets hardware copy a block without a CPU store instruction for every byte. Writing a source-page number to $FF46 requests an OAM transfer.",
         "<p>A request value $XX identifies a page beginning at $XX00. OAM DMA transfers 160 bytes from that page into $FE00–$FE9F, one byte per machine cycle; the transfer itself is not a series of CPU write callbacks. Normal DMG transfer work takes 160 M-cycles, or 640 dots.</p><p>Most of the DMG CPU bus is restricted during the transfer. Games commonly execute a small start/wait routine from HRAM, which remains accessible. Changing the source or interrupt behavior while the transfer is underway can complicate the outcome.</p>",
         "<p>A game builds a shadow sprite table in WRAM, then requests one copy to update OAM. This separates game calculations from the hardware's sprite records. An OAM byte can therefore change because of DMA even when no CPU instruction directly wrote its address.</p>",
         "<p>This app records the request instruction and source page, then compares OAM with sampled source bytes after a conservative completion boundary. A match is evidence of compatible values, not proof that each byte came from that request. Later stores or a restarted DMA can affect the result. Source links open current retained CPU write evidence, not a replay of the entire transfer.</p>",
         {"oam", "wram", "hram", "writes", "interrupts", "time"}},
        {"interrupts", "Interrupts · responding to hardware events",
         "Interrupts let hardware request that the CPU run a handler. The five sources are VBlank, LCD STAT, timer, serial, and joypad. A request and an executed handler are different events.",
         "<p>IF at $FF0F stores request bits; IE at $FFFF enables selected sources. Bits 0–4 correspond to those five sources. The CPU also has an internal interrupt master enable (IME), controlled by instructions such as EI, DI, and RETI. When an eligible request is serviced, the CPU saves its return address on the stack and jumps to the corresponding vector ($0040, $0048, $0050, $0058, or $0060).</p><p>Interrupt entry disables IME until code enables it again; EI takes effect after the following instruction. HALT can wait for activity, with wakeup behavior depending on pending interrupts and enable state. Waiting and interrupt entry can advance time without an ordinary opcode callback.</p>",
         "<p>A VBlank handler can schedule graphics work, while a timer handler can maintain a software clock. Interrupts help code respond without constantly polling every device. The program still decides what each handler does.</p>",
         "<p>IF and IE are visible storage; IME is not exposed as an invented memory byte. Their values alone do not prove a handler ran. The engine tests interrupt/HALT stepping and does not assign the previous opcode to writes made by interrupt-entry work. This release provides explanation and current observations, not a full interrupt timeline.</p>",
         {"cpu", "stack", "stat", "timers", "joypad", "time"}},
        {"timers", "Timers and divider · counting hardware time",
         "The console's divider and timer count clock activity. They are distinct from a cartridge's battery-backed real-time clock and from the app's wall-clock pacing timer.",
         "<p>DIV at $FF04 exposes part of the internal divider and increments at 16,384 Hz in normal DMG operation. Writing any value resets the divider rather than storing that value. TIMA at $FF05 is the programmable timer counter; TMA at $FF06 provides its reload value.</p><p>TAC at $FF07 enables TIMA and chooses a divider-derived input: 4,096, 262,144, 65,536, or 16,384 Hz. Overflow causes a delayed reload from TMA and an interrupt request, with hardware edge/reload details that matter to timing-sensitive programs. Changing DIV/TAC can itself affect the selected edge; this is more than a software counter incremented once per frame.</p>",
         "<p>Games can use timer interrupts for repeated work, music sequencing, or timekeeping that is independent of the display refresh. A halted CPU can wait while timer hardware continues to progress.</p>",
         "<p>The values shown are raw register storage at the snapshot boundary. A requested DIV write is not expected to read back as the written byte. The app does not yet display every internal divider edge or reload event; the explanation describes hardware behavior without claiming those events were individually captured.</p>",
         {"io", "interrupts", "cpu", "time", "cartridge"}},
        {"audio", "Audio hardware · registers that shape sound",
         "The Game Boy audio processing unit (APU) has two pulse channels, one wave channel, and one noise channel. Its control registers occupy much of $FF10–$FF3F.",
         "<p>Pulse channels produce repeating high/low patterns with selectable duty cycles. The wave channel reads a small table of four-bit samples from wave RAM at $FF30–$FF3F. The noise channel uses a shift-register sequence. Controls set frequency, length, volume envelopes, triggers, output routing, and overall power; some are read-only or have special readback behavior.</p><p>The hardware evolves over time after a trigger, so the current register byte is not a complete representation of the generated waveform.</p>",
         "<p>Game code writes these registers to create music and effects. A captured CPU store can identify one command and the instruction responsible, while memory and timing observations help connect it with the program.</p>",
         "<p>The core emulates audio hardware, but this app does not play sound or provide channel-waveform/event inspectors. It shows raw copied register/wave storage and retained CPU attempts. This reference explains the hardware role without claiming an audible result or complete audio state from those bytes alone.</p>",
         {"io", "timers", "writes", "time", "memory"}},
        {"serial", "Serial port · sending and receiving bits",
         "The serial hardware supports link-cable communication. SB at $FF01 holds transfer data; SC at $FF02 controls a transfer and its clock choice.",
         "<p>A transfer shifts eight bits out while shifting received bits in. One side can supply the clock while the other uses an external clock. At completion, the serial hardware can request its interrupt. Writing a control byte requests behavior over time rather than a one-step copy between two ordinary RAM bytes.</p>",
         "<p>Games use the link cable to exchange player input, game data, or accessory commands. Some test programs also use serial output as a debugging convention; that meaning is supplied by the test program, not by the register itself.</p>",
         "<p>The inspector shows raw serial register storage and CPU write attempts. This application does not implement a connected second console, link-cable UI, or a full serial-bit timeline. An observed start command therefore does not establish successful communication with another device.</p>",
         {"io", "interrupts", "writes", "time"}},
        {"boot", "Boot mapping · handing control to the game",
         "At power-on, a boot program initializes the console before the cartridge entry point runs. During startup, its bytes temporarily cover part of the low address space.",
         "<p>In this DMG lab, the boot program occupies $0000–$00FF while mapped. It writes $FF50 to remove that overlay and hand execution to the cartridge. The address remains the same, but the source of its storage changes.</p><p>The app bundles an original source-built startup program that establishes the expected DMG post-boot state. It does not redistribute Nintendo's proprietary boot ROM. Bundled examples are warmed to a useful visible frame; arbitrary ROMs start paused at power-on.</p>",
         "<p>Startup explains why PC and low ROM contents can look different immediately after loading compared with a running game. The cartridge header and entry point belong to the ROM even while part of the boot overlay is visible.</p>",
         "<p>The mapping flag is observed through the pinned public core API. Boot execution is counted separately from cartridge-bank activity, and source annotations require exact ROM identity. The startup program is a documented replacement, not a claim of identical proprietary boot instructions.</p>",
         {"rom", "cpu", "cartridge", "activity", "io"}},
        {"activity", "Memory activity · where the CPU did work",
         "The memory activity map summarizes CPU write attempts and opcode starts over a labeled interval. It is an access map, not a picture of current byte values.",
         "<p>The overview contains the full 64 KiB CPU address space, with one row per 256-byte page. Selecting a page reveals its addresses in detail. Colour intensity uses a logarithmic scale to make both occasional and frequent activity visible. Modes show writes, executions, or both.</p><p>Cartridge activity also counts execution by physical ROM bank, because the same CPU address can reach different code. Clearing the map starts a new interval at the current emulated time.</p>",
         "<p>Bright execution areas can suggest loops or frequently called routines. Write concentrations can suggest working data or graphics updates. These are clues for inspection, not automatic labels such as player health or level state. Select an address to inspect its storage and relevant retained writer.</p>",
         "<p>Counts cover CPU attempts and opcode starts, not all bus reads, PPU tile fetches, or DMA byte transfers. The interval may span many frames and differs from both the current state boundary and bounded write history. CPU aliases can have separate counts; unmapped cartridge banks still retain their own aggregate execution counts.</p>",
         {"memory", "writes", "banks", "cpu", "time"}},
        {"writes", "Captured writes · evidence of a store attempt",
         "A captured write records a CPU attempt to store a value, together with the executing instruction when known, its bank, and the enclosing step interval. It is evidence to inspect, not a replay cursor.",
         "<p>The core callback occurs before acceptance. The app never suppresses the write and does not equate a callback with an accepted bus write. For ordinary physical RAM, copied before/after values provide evidence of a storage change. For IO or ROM/controller addresses, those bytes can have different meanings.</p><p>The requested value is what the CPU tried to write. A ROM-range attempt can command an MBC; a DMA-register write can initiate hardware work. Interrupt/wait work can have no opcode identity. Event start/end times enclose an atomic step rather than locating every write on an exact bus cycle.</p>",
         "<p>Selecting a row links its address to Memory while leaving the machine at its current time. Selecting a byte searches retained compatible evidence, including bank identity and WRAM mirrors. A source link from OAM DMA opens current retained evidence for the source location.</p>",
         "<p>The ring is bounded (4,096 records by default); the list shows the newest 64, and evicted history is labeled incomplete. Capture changes start a fresh record. A missing writer does not mean a byte never changed. DMA/PPU changes are not fabricated as CPU stores, and a last attempt is not a complete explanation of all earlier calculations or future effects.</p>",
         {"memory", "instructions", "banks", "dma", "activity", "time"}},
        {"time", "Time · state, pictures, and recorded intervals",
         "The app separates the current machine boundary, completed display output, and historical intervals. They can describe different times even while all panels are synchronized correctly.",
         "<p>State now is emulated time since power-on, in 8,388,608 Hz ticks (two ticks per normal DMG clock cycle). CPU registers, copied memory, video storage, and cartridge mapping share that boundary. The picture has its own output number and completion boundary.</p><p>A write event records an enclosing interval; activity summarizes a labeled span. These are not identical to the current snapshot time. At normal DMG speed a standard frame is 70,224 dots, or 140,448 app ticks, about 16.74 ms. Emulator output during startup or LCD-disabled periods is labeled separately.</p>",
         "<p>Instruction stepping finishes one opcode when possible, including necessary hardware progress. Frame stepping waits for the next completed output and finishes its enclosing step. Live execution uses bounded main-thread quanta so the UI can respond. Paused reading and selection do not advance emulated time.</p>",
         "<p>The CPU can be halted while timers/PPU still advance during an explicit step. Selecting captured evidence does not rewind the machine, and current storage cannot reconstruct every historical pixel fetch. The explanation panel updates compact observed facts as execution advances but keeps its topic and reading position stable until another selection.</p>",
         {"cpu", "display", "ppu", "writes", "activity", "timers"}}
    };
    return articles;
}
const InformationArticle* informationArticle(const std::string& id) {
    const auto& a = informationArticles();
    const auto found = std::find_if(a.begin(), a.end(), [&id](const auto& v) { return v.id == id; });
    return found == a.end() ? nullptr : &*found;
}
std::string informationTopicForAddress(std::uint16_t a) {
    if (a < 0x8000) return "rom";
    if (a < 0x9800) return "tile-data";
    if (a < 0xA000) return "tile-map";
    if (a < 0xC000) return "cart-ram";
    if (a < 0xE000) return "wram";
    if (a < 0xFE00) return "echo";
    if (a < 0xFEA0) return "oam";
    if (a < 0xFF00) return "unusable";
    if (a == 0xFF00) return "joypad";
    if (a <= 0xFF02) return "serial";
    if (a >= 0xFF04 && a <= 0xFF07) return "timers";
    if (a == 0xFF0F || a == 0xFFFF) return "interrupts";
    if (a >= 0xFF10 && a <= 0xFF3F) return "audio";
    if (a == 0xFF40) return "lcdc";
    if (a == 0xFF41 || a == 0xFF44 || a == 0xFF45) return "stat";
    if (a == 0xFF42 || a == 0xFF43) return "scroll";
    if (a == 0xFF46) return "dma";
    if (a >= 0xFF47 && a <= 0xFF49) return "palettes";
    if (a == 0xFF4A || a == 0xFF4B) return "window";
    if (a == 0xFF50) return "boot";
    if (a >= 0xFF80 && a < 0xFFFF) return "hram";
    return "io";
}
std::string informationTopicForGlossary(const std::string& key) {
    if (key == "reg.sp") return "stack";
    if (key == "reg.pc" || key == "cpu.instruction") return "instructions";
    if (key.starts_with("reg.")) return "registers";
    if (key.starts_with("flag.")) return "flags";
    if (key == "cart.save") return "battery";
    if (key.starts_with("cart.")) return "banks";
    if (key.starts_with("writes.")) return "writes";
    if (key.starts_with("tiles.")) return "tile-data";
    if (key.starts_with("map.")) return "activity";
    if (key == "ui.frame" || key == "ui.game") return "display";
    if (key == "ui.cursor" || key == "ui.activity" || key == "ui.badge") return "time";
    return "explore";
}
} // namespace observatory
